function heading(k,t,p){return `<div class="sectionTop"><div><p class="eyebrow">${k}</p><h2>${t}</h2><p>${p}</p></div></div>`}
function sourceNote(id,text){return `<p class="sourceNote">מקור: <a target="_blank" rel="noopener" href="https://drive.google.com/file/d/${id}/view">${text} ↗</a></p>`}
function diagnosis(){return heading('נתונים → אתגר → למידה → שינוי','תמונת מצב מבוססת נתונים','יסודי אלמג׳ד ב׳ אל־מכסור · סמל מוסד 218230')+`<div class="target"><div><small>נקודת מוצא — מתוך המסמך „כללי”</small><p>410 תלמידים · 19 כיתות · שלב חינוך יסודי</p></div></div><h3>האתגר המוצע מתוך מסמכי העבודה</h3><p class="reading">${schoolSeed.challenge}</p><p class="sourceNote">מוקד הפעולה הסופי דורש אימות עם הצוות המוביל; בפרוטוקול 30/9 נדרשת השלמת נתונים ותעדוף.</p><h3>מטרה מרכזית</h3><p class="reading">${schoolSeed.goals}</p><button id="applyProfile">הוספת פרופיל בית הספר לרשימה שלי</button><h3>שבע הזירות — השוואת 2025 ל־2026</h3><div class="metricGrid"><div><small>ממוצע 2025</small><b>3.14</b></div><div><small>ממוצע 2026</small><b>3.77</b></div><div><small>שינוי לפי מסמך ההשוואה</small><b>+0.63</b></div></div><div class="tableWrap"><table><thead><tr><th>זירה</th><th>2025</th><th>2026</th><th>שינוי</th></tr></thead><tbody>${baseline.map(r=>`<tr><td>${r[0]}</td><td>${r[1].toFixed(2)}</td><td><div class="score"><i style="width:${r[2]/5*100}%"></i><span>${r[2].toFixed(2)}</span></div></td><td class="positive">+${(r[2]-r[1]).toFixed(2)}</td></tr>`).join('')}</tbody></table></div><p class="sourceNote">הציונים משקפים תפיסת מצב בסולם 1–5; הם אינם מוכיחים סיבתיות או שינוי בפועל בכיתה. המסמך „כללי” מציג טווחים שונים; כאן מוצגים הממוצעים המספריים ממסמך ההשוואה, בלי למזג בין המקורות.</p>${sourceNote('1CiWW3F2Mm5olhr6kxjkRwfFWfMAXlnos','השוואת ממצאי שבע הזירות 2025–2026')}<h3>מגדירים את המענה</h3>${field('האתגר המוסכם לאחר השלמת האבחון','agreedChallenge','textarea')}<div class="fields">${field('פער פדגוגי — מענה בפיתוח מקצועי','pedagogical','textarea')}${field('פער ארגוני — תנאים, משאבים ושותפויות','organizational','textarea')}${field('השינוי הרצוי אצל המורים','teacherOutcome','textarea')}${field('השינוי הרצוי אצל התלמידים','studentOutcome','textarea')}${field('נקודת ייחוס, מדדים וכלי איסוף ראיות','baselineEvidence','textarea')}</div>`}
function decisions(){return `<h3>החלטות מפרוטוקול 30/9/2026</h3><p class="sourceNote">המועדים הם כפי שתועדו בפרוטוקול. חלוף המועד אינו עדות לביצוע; נדרש עדכון סטטוס.</p>${sourceTasks.map((t,i)=>`<div class="decision"><b>${t[0]}</b><p>${t[1]} · יעד מקורי: ${t[2].split('-').reverse().join('/')}</p><label class="field">סטטוס<select data-decision="${i}">${['טרם אומת','בתהליך','הושלם','נדחה'].map(s=>`<option ${data.decisions[i]?.status===s?'selected':''}>${s}</option>`).join('')}</select></label><label class="field">ראיה לביצוע / הערה<input data-evidence="${i}" value="${esc(data.decisions[i]?.evidence)}" placeholder="קישור לתוצר או עדכון קצר"></label></div>`).join('')}${sourceNote('1G2sAR0-uXSPOI59SR0JbnWAh5uJYe5y22PipaGfsvpE','פרוטוקול ישיבה 3')}`}
function meetingView(){return heading('משגרה להחלטה ולעשייה','מפגשים ומשימות','שגרת עבודה בין צוות פסג״ה לצוות המוביל הבית־ספרי')+`<div class="target"><span class="targetIcon">◷</span><div><small>הסדירות שנקבעה במסמך</small><p>יום שלישי · 09:00–10:30 · אחת לשבועיים או לחודש, בהתאם לצורך</p></div></div><details><summary>מבנה מפגש מוצע — 90 דקות</summary><ul class="reading"><li>09:00–09:10 · פתיחה ותמונת מצב</li><li>09:10–09:30 · בחינת היישום: מה תוכנן ומה בוצע</li><li>09:30–09:50 · נתונים, ראיות ופרשנות</li><li>09:50–10:10 · חסמים והתאמות</li><li>10:10–10:25 · החלטות להמשך, אחראים ומועדים</li><li>10:25–10:30 · סיכום ותיעוד</li></ul></details>${sourceNote('1N4eXXD3qpY80sz4Xn1I7MAGqfkX7oRKZ','שגרות עבודה 67')}${decisions()}<hr class="divider"><h3>תיעוד מפגש חדש</h3><div class="fields">${field('תאריך מפגש','meetingDate','date')}${field('משתתפים','meetingPeople')}${field('תמונת מצב ובחינת החלטות קודמות','meetingState','textarea')}${field('יישום בפועל וראיות שנבחנו','meetingEvidence','textarea')}${field('חסמים, רפלקציה והתאמות','meetingReflection','textarea')}${field('החלטות, בעלי אחריות, מועדים והצעד הבא','meetingDecisions','textarea')}</div><button class="primary" id="saveMeeting">שמירת מפגש ביומן</button><h3>יומן המפגשים שלי</h3>${data.meetings.length?data.meetings.map(m=>`<details class="decision"><summary>${esc(m.date)} · ${esc(m.people||'מפגש צוות')}</summary>${[['תמונת מצב',m.state],['ראיות',m.evidence],['רפלקציה',m.reflection],['החלטות',m.decisions]].map(r=>`<h4>${r[0]}</h4><p class="reading pre">${esc(r[1]||'לא הוזן')}</p>`).join('')}</details>`).join(''):'<p class="sourceNote">טרם נשמרו מפגשים אישיים. הפרוטוקולים המקוריים זמינים בספריית המסמכים.</p>'}`}
function library(){return heading('תיק הפיילוט המשותף','ספריית מסמכים','קישורים למקורות ב־Google Drive · נדרשות הרשאות הגישה המקוריות')+`<p class="sourceNote">עודכן מתוך החומרים ב־26/10/2026. זהו עדכון תוכן חד־פעמי; שינויים ב־Drive אינם מסתנכרנים אוטומטית. החוברת והמודולות זמינות כמקורות לעיון ולא הוצגו כטקסט שנקרא במלואו.</p><div class="docGrid">${driveDocs.map(d=>`<a class="doc" href="${docUrl(d)}" target="_blank" rel="noopener"><span>${d[3]}</span><b>${d[0]}</b><small>פתיחה ב־Google Drive ↗</small></a>`).join('')}</div><h3>תיקיות המקור</h3><a class="folderLink" target="_blank" rel="noopener" href="https://drive.google.com/drive/folders/13yCqZ1EpVmnr1bi2CmvBkBV5DuQ9wn_Z">יד מכוונת — פרויקט מוביל ניהול למידה ↗</a><a class="folderLink" target="_blank" rel="noopener" href="https://drive.google.com/drive/folders/16cjkDobKGO2R413cfK070LCOILeMGOcM">יסודי אלמג׳ד ב׳ אל־מכסור ↗</a><h3>הצוות המוביל — חלוקת אחריות</h3><div class="reading">מנהל מרכז פסג״ה — הובלה מערכתית והסרת חסמים.<br>מוביל הפיילוט — תכלול, אבני דרך ומעקב ביצוע.<br>מלווה בית הספר — שותפות, ליווי יישום ורפלקציה.<br>הערכה ומדידה — מדדים, ראיות ותמונת מצב.<br>מנחה מקצועי — התאמת הלמידה לצורך ולפרקטיקה.<br>תפעול ותיעוד — סיכומי החלטות, מסמכים ומעקב משימות.</div>${sourceNote('1x-UFig5DTbeMnh7DHVYBl0bek6ar01aE','הרכב הצוות וחלוקת תפקידים')}`}
render=function(){data.decisions=data.decisions||sourceTasks.map(()=>({status:'טרם אומת',evidence:''}));data.meetings=data.meetings||[];originalRender();if(view==='diagnosis')$('content').innerHTML=diagnosis();if(view==='meetings')$('content').innerHTML=meetingView();if(view==='library')$('content').innerHTML=library();if(view==='journey'){$('content').insertAdjacentHTML('afterbegin','<p class="sourceNote">רשימת העבודה עודכנה לפי חומרי Drive. סימונים מהגרסה הקודמת נשמרו בגיבוי הנתונים, ויש לאמת מחדש את המשימות המעודכנות.</p>');if(data.stage===1)$('content').insertAdjacentHTML('beforeend','<button data-view="diagnosis" class="primary">למיפוי שבע הזירות והגדרת המענה ←</button>');if(data.stage===3)$('content').insertAdjacentHTML('beforeend','<button data-view="meetings" class="primary">לתיעוד מפגשים ומעקב החלטות ←</button>')}};
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.decision!==undefined){data.decisions[+t.dataset.decision].status=t.value;save()}});document.addEventListener('input',e=>{const t=e.target;if(t.dataset.evidence!==undefined){data.decisions[+t.dataset.evidence].evidence=t.value;save()}});
document.addEventListener('click',e=>{if(e.target.closest('#applyProfile')){if(data.schools.some(s=>s.code==='218230'))return toast('בית הספר כבר קיים ברשימה שלך');data.schools.push({...schoolSeed});save();toast('פרופיל בית הספר נוסף לרשימה')}if(e.target.closest('#saveMeeting')){const f=data.fields;if(!f.meetingDate||!f.meetingDecisions)return toast('יש להזין תאריך והחלטות לפני שמירת המפגש');data.meetings.unshift({date:f.meetingDate,people:f.meetingPeople,state:f.meetingState,evidence:f.meetingEvidence,reflection:f.meetingReflection,decisions:f.meetingDecisions});['meetingDate','meetingPeople','meetingState','meetingEvidence','meetingReflection','meetingDecisions'].forEach(k=>delete f[k]);save();render();toast('המפגש נשמר ביומן')}});
document.querySelector('.intro h1').textContent='יד מכוונת. שינוי בכיתה.';document.querySelector('.intro p:not(.eyebrow)').textContent='מרכז פסג״ה אזורי שפרעם · פיילוט 67/67 · ליווי מבוסס נתונים, פרקטיקה ורפלקציה';
save();render();
